var m1=[s[0]+dir[0]*L*0.32+side[0]*j1,s[1]+(b.dy-0.1)*S,s[2]+dir[2]*L*0.32+side[2]*j1];
var mid=[s[0]+dir[0]*L*0.62+side[0]*j2,s[1]+(b.dy-0.08)*S,s[2]+dir[2]*L*0.62+side[2]*j2];
