var fo={pal:hp,center:[t.x,t.H*0.6,t.z],R:t.R*1.6,kind:'oval',dab:0.075,density:0.9,max:120,seed:t.seed+1,snow:0.7*SEA.snowT,tint:LIT.foliageTint,mass:0.7,flat:0.62,litBase:0.36,litK:0.7};
