for(j=0;j<=N;j++){cs.push((lo[j]+hi[j])/2);ws.push((hi[j]-lo[j])/2);}
for(j=1;j<N;j++)ws[j]=Math.max(ws[j],(ws[j-1]+ws[j+1])/2*0.96);
