ctx.beginPath();ctx.moveTo(px-dy/dl*ll,py+dx/dl*ll*0.6);ctx.lineTo(px,py);ctx.lineTo(px+dy/dl*ll,py-dx/dl*ll*0.6);ctx.stroke();
