function nobeFrame(){var dx=NOBE.b[0]-NOBE.a[0],dz=NOBE.b[1]-NOBE.a[1],L=Math.hypot(dx,dz);return{L:L,ux:dx/L,uz:dz/L,vx:-dz/L,vz:dx/L};}
