ctx.strokeStyle=rgb(shade([140,120,92],[0,1,0]));ctx.lineWidth=Math.max(0.5,0.035*a2.k);ctx.beginPath();ctx.moveTo(a2.x,a2.y);ctx.lineTo(b2.x,b2.y);ctx.stroke();
